def handler(events, context):
    import boto3
    cw = boto3.client('cloudwatch')
    alarms = cw.describe_alarms(AlarmNames=['dr-primary-alb-unhealthy'])
    if not alarms['MetricAlarms']:
        raise Exception('Alarm not found. Check alarm name.')
    state = alarms['MetricAlarms'][0]['StateValue']
    if state != 'ALARM':
        raise Exception(f'Primary appears healthy (state={state}). Aborting DR. Use ManualOverride=true to bypass.')
    return {'primary_alarm_state': state, 'proceed': True}

def handler(events, context):
    import boto3
    asg = boto3.client('autoscaling', region_name=events['DRRegion'])
    resp = asg.describe_auto_scaling_groups(AutoScalingGroupNames=[events['DRASGName']])
    instances = resp['AutoScalingGroups'][0]['Instances']
    healthy = [i for i in instances if i['HealthStatus'] == 'Healthy']
    if len(healthy) == 0:
        raise Exception(f'No healthy instances in DR ASG yet. Total instances: {len(instances)}')
    return {'healthy_count': len(healthy), 'total_count': len(instances), 'status': 'DR_ACTIVE'}

def handler(events, context):
    import boto3, time
    rds = boto3.client('rds', region_name=events['DRRegion'])
    for attempt in range(20):
        resp = rds.describe_db_instances(DBInstanceIdentifier=events['DRReplicaId'])
        db = resp['DBInstances'][0]
        status = db['DBInstanceStatus']
        is_replica = bool(db.get('ReadReplicaSourceDBInstanceIdentifier'))
        if status == 'available' and not is_replica:
            return {'rds_status': status, 'is_standalone': True, 'endpoint': db['Endpoint']['Address']}
        time.sleep(30)
    return {'rds_status': status, 'is_standalone': False, 'note': 'Still promoting — check console'}
